{
    SolarMutexReleaser aRel;

    Sequence< sal_Int8 > aSeq( static_cast<const sal_Int8*>(pData), nBytes );
    Any aEvent;
    aEvent <<= aSeq;
    ::std::vector< css::uno::Reference< XEventHandler > > handlers;
    {
